{
  "candidate_facts_list": [
    {
      "fact": "Cross-project refs resolve to Production by default; if a project defines both Production and Staging, refs from development and Staging environments resolve to Staging while refs from Production resolve to Production.",
      "quote": "By default, cross-project references resolve to the \"Production\" deployment environment... If a project defines both a \"Production\" environment and a \"Staging\" environment, then cross-project references from development and \"Staging\" environments will resolve to \"Staging,\" whereas only references coming from \"Production\" environments will resolve to \"Production.\"",
      "technical_level": "configuration",
      "supports_objective": "Understanding how environment types relate to cross-project references"
    },
    {
      "fact": "Contracts can only be applied at the model level and apply to the entire model, including all output columns; you cannot apply contracts to sources or to part of a model.",
      "quote": "No, contracts can only be applied at the model level. No. A contract applies to an entire model, including all columns in the model’s output.",
      "technical_level": "constraint",
      "supports_objective": "Utilizing model governance"
    },
    {
      "fact": "Protected is the default access: protected models can be referenced by any model within the same dbt project or when the project is installed as a package.",
      "quote": "Protected: Models with a protected access modifier can be referenced by any other model within the same dbt project or when the project is installed as a package. This is the default setting for all models...",
      "technical_level": "configuration",
      "supports_objective": "Utilizing model governance"
    },
    {
      "fact": "Private models are referenceable only by models within the same group.",
      "quote": "Private: A model with a private access modifier is only referenceable by models within the same group.",
      "technical_level": "configuration",
      "supports_objective": "Utilizing model governance"
    },
    {
      "fact": "To deprecate a model (or downgrade its access), mark it with deprecation_date to deliver a warning to all downstream consumers.",
      "quote": "they should mark that model for deprecation (using deprecation_date), which will deliver a warning to all downstream consumers of that model.",
      "technical_level": "procedure",
      "supports_objective": "Utilizing model governance"
    },
    {
      "fact": "Cross-project references require each project name to be unique in your dbt account.",
      "quote": "Cross-project references require that each project `name` be unique in your dbt account.",
      "technical_level": "constraint",
      "supports_objective": "Understanding how environment types relate to cross-project references"
    },
    {
      "fact": "To enable bidirectional project dependencies, each project must run and produce public models before the other can take a dependency on it.",
      "quote": "Each project must run and produce public models before the original producer project can take a dependency on the original consumer project.",
      "technical_level": "procedure",
      "supports_objective": "Understanding how environment types relate to cross-project references"
    },
    {
      "fact": "Running `dbt build --select +model` will not run upstream models in other projects unless those upstream projects are installed as packages (source code).",
      "quote": "No, unless upstream projects are installed as packages (source code). In that case, the models in project installed as a project become \"your\" models, and you can select or run them.",
      "technical_level": "implementation",
      "supports_objective": "Understanding how environment types relate to cross-project references"
    },
    {
      "fact": "A dbt Enterprise-tier plan is required to set up multiple projects and reference models across them.",
      "quote": "Yes, a dbt Enterprise-tier plan is required to set up multiple projects and reference models across them.",
      "technical_level": "constraint",
      "supports_objective": "Utilizing model governance"
    }
  ]
}

{
  "candidate_facts_list": [
    {
      "fact": "Built-in job commands are chained; if one run step fails the entire job fails with an \"Error\" status.",
      "quote": "During a job run, built-in commands are \"chained\" together and if one run step fails, the entire job fails with an \"Error\" status.",
      "technical_level": "implementation",
      "supports_objective": "Understanding steps within a dbt job"
    },
    {
      "fact": "Checkbox steps like 'Generate docs on run' or 'Run source freshness' can fail without failing the whole job if subsequent steps pass.",
      "quote": "If the step fails, the job can succeed if subsequent steps pass.",
      "technical_level": "implementation",
      "supports_objective": "Understanding steps within a dbt job"
    },
    {
      "fact": "By default a deploy job's Commands section includes the dbt build command.",
      "quote": "By default, it includes the `dbt build` command.",
      "technical_level": "configuration",
      "supports_objective": "Creating a new dbt job"
    },
    {
      "fact": "Intervals scheduling runs every N hours from midnight UTC; subsequent runs keep the same offset (e.g., 00:04 -> 02:04 for Every 2 hours).",
      "quote": "If you choose **Every 2 hours**, the job will run every 2 hours from midnight UTC. ... if the previous scheduled pipeline ran at 00:04 UTC, the next run will be at 02:04 UTC.",
      "technical_level": "constraint",
      "supports_objective": "Scheduling a job to run on schedule"
    },
    {
      "fact": "dbt job schedules use UTC and do not translate to local time or account for daylight savings.",
      "quote": "dbt uses Coordinated Universal Time (UTC) and does not account for translations to your specific timezone or take into consideration daylight savings time.",
      "technical_level": "constraint",
      "supports_objective": "Scheduling a job to run on schedule"
    },
    {
      "fact": "Developer plans enforce a minimum cron scheduling interval of 10 minutes; Starter/Enterprise plans have no execution-frequency restrictions.",
      "quote": "Developer plans: dbt sets a minimum interval of every 10 minutes for scheduling jobs. ... Starter, Enterprise, and Enterprise+ plans: No restrictions on job execution frequency.",
      "technical_level": "constraint",
      "supports_objective": "Scheduling a job to run on schedule"
    },
    {
      "fact": "The 'Run when another job finishes' trigger (job chaining) requires a Starter or Enterprise-tier dbt plan.",
      "quote": "For the [Trigger on job completion] feature, your dbt account must be on the [Starter or an Enterprise-tier] plan.",
      "technical_level": "constraint",
      "supports_objective": "Configuring jobs to be triggered after other dbt jobs (job chaining)"
    },
    {
      "fact": "By default a job inherits the dbt version from its environment; changing the job-level version is discouraged except for upgrades.",
      "quote": "By default, it\u0019s set to inherit the dbt version from the environment. dbt Labs strongly recommends that you don't change the default setting.",
      "technical_level": "configuration",
      "supports_objective": "Configuring optional settings such as environment variable overrides, threads, deferral, target name, and dbt version override"
    },
    {
      "fact": "Job 'Threads' defaults to 4; increasing threads raises model execution concurrency.",
      "quote": "By default, it\u0019s set to 4 threads. Increase the thread count to increase model execution concurrency.",
      "technical_level": "configuration",
      "supports_objective": "Configuring optional settings such as environment variable overrides, threads, deferral, target name, and dbt version override"
    },
    {
      "fact": "Compare changes 'No deferral' is default; options are 'Environment' or 'This Job' and deferral-to-environment compares against the environment's manifest.json.",
      "quote": "By default, it\u0019s set to **No deferral**. Select either **Environment** or **This Job**... deferral to an environment is more efficient as dbt will compare against the project representation (which is stored in the `manifest.json`) of the last successful deploy job run that executed in the deferred environment.",
      "technical_level": "implementation",
      "supports_objective": "Understanding when to use which type of job deferral"
    }
  ]
}
